def emit_csv(headers: Sequence[str], rows: Sequence[Sequence[str]], out: TextIO) -> None:
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(headers)
    writer.writerows(rows)


def run(argv: Sequence[str] | None = None) -> None:
    args = build_parser().parse_args(argv)
    filters = parse_filters(args.where)
    has_aggregation = bool(args.sum_columns or args.avg_columns)
    if has_aggregation and not args.group_by:
        raise CsvInsightsError("--sum and --avg require --group-by")
    if args.group_by and not has_aggregation:
        raise CsvInsightsError("--group-by requires --sum or --avg")

    headers, numbered_rows = read_csv(Path(args.input))
    requested_columns = [column for column, _ in filters]
    requested_columns.extend(args.sum_columns)
    requested_columns.extend(args.avg_columns)
    if args.group_by:
        requested_columns.append(args.group_by)
    validate_columns(requested_columns, headers)
    numbered_rows = selected_rows(headers, numbered_rows, filters)

    if has_aggregation:
        output_headers, output_rows = aggregate(
            headers,
            numbered_rows,
            args.group_by,
            args.sum_columns,
            args.avg_columns,
        )
    else:
        output_headers = headers
        output_rows = [values for _, values in numbered_rows]

    if args.output == "json":
        emit_json(output_headers, output_rows, sys.stdout)
    else:
        emit_csv(output_headers, output_rows, sys.stdout)


def main() -> int:
    try:
        run()
    except CsvInsightsError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except BrokenPipeError:
        return 0
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
# CSV Insights

A dependency-free Python 3.11+ command-line tool for filtering and aggregating
CSV data. It uses exact string matching for filters and `decimal.Decimal` for
numeric calculations.

```console
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN] \
  [--sum COLUMN] [--avg COLUMN] [--output json|csv]
```

Output defaults to JSON. Filters can be repeated and are combined with AND.
`--sum` and `--avg` can each be repeated, and require `--group-by`.

Examples:

```console
python3 main.py sales.csv --where region=East
python3 main.py sales.csv --group-by region --sum revenue --avg units
python3 main.py sales.csv --where active=yes --output csv
```

Malformed CSV, invalid headers or row widths, unknown columns, and invalid
numeric cells produce a diagnostic on stderr and a non-zero exit status. The
input file is opened read-only and is never modified.
